get_dashboard_kpi_options.code:
final response = await client.dashboardKpis.getDashboardKpiOptions();
final options = response.map as Map;
print('${options['min']} ${options['max']} ${options['selected']}');
for (final group in options['groups'] as List) {
  for (final metric in (group as Map)['metrics'] as List) {
    print('${group['key']} ${(metric as Map)['key']} ${metric['label']}');
  }
}

get_dashboard_kpi_selection.code:
final response = await client.dashboardKpis
    .getDashboardKpiSelection(queryParams: {'duration': 'last_7_days'});
for (final kpi in (response.map as Map)['selected'] as List) {
  print('${(kpi as Map)['key']} ${kpi['value']} ${kpi['change_percent']}');
}

update_dashboard_kpi_selection.code:
final response = await client.dashboardKpis.updateDashboardKpiSelection(
  {
    'metrics': ['total_sales', 'total_orders', 'aov'],
  },
  queryParams: {'duration': 'last_7_days'},
);
for (final kpi in (response.map as Map)['selected'] as List) {
  print('${(kpi as Map)['position']} ${kpi['key']} ${kpi['value']}');
}
